SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);Alarm(500);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C54/expanded_forward.m";load "work/deg10/continuation_20261031b/C54/inputs/pair_af_place_linear.m";
root:="work/deg10/continuation_20261031b/C54/";a:=eval Read(root cat "inputs/target27_proven_picard.m");k:=GF(5);PK:=PolynomialRing(k);B<t>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;F<y>:=FunctionField(R![Rat(v):v in a[1]]);assert Genus(F)eq 13;
function FF(v)return F![Rat(z):z in v];end function;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function Prime(v)O:=v[2]eq 1 select OF else OI;I:=ideal<O|[FF(z):z in v[3]]>;p:=Place(I);assert Degree(p)eq v[1];return p;end function;
fb:=[Prime([*a[3][i],a[2][i],a[4][i]*]):i in[1..#a[3]]];A:=Divisor(Prime(a[12]));Z:=FreeAbelianGroup(#a[6][1]);G,q:=quo<Z|[Z!v:v in a[6]]>;H:=sub<G|[q(Z!v):v in a[13]]>;fc:=[q(Z!v):v in a[5]];basehit:=[i:i in[1..#fb]|Divisor(fb[i])eq A];assert #basehit eq 1;ac:=fc[basehit[1]];
for d in[5,6]do ex:=eval Read(root cat Sprintf("expanded_d%o.m",d));for row in ex do Append(~fb,Prime(row[1]));Append(~fc,q(Z!row[2])+d*ac);end for;end for;print "D31B_C54_EXPANDED_FRAME_READY",#fb,Cputime(tt);coords:=[FF(v):v in a[7]];ph,wh:=C54ExpandedDirectRR(F,fb,fc,G,A,root cat "profile100_expanded_class.log");src:=eval Read(root cat "profile100_input.m");fs:=AssociativeArray();for z in src[1]do fs[z[1]]:=ext<k|PK!z[2]>;end for;rows:=[* *];tm:=Cputime();for row in src[2]do d,ky:=Explode(row);K:=fs[d];b:=Evaluate(PK!ky[1..d],K.1);c:=Evaluate(PK!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];assert 54*P eq E!0 and 27*P ne E!0 and 18*P ne E!0;xy:=TateNormalForm_xy(E,2*P);pt:=C48PairAFPlaceLinear(coords,xy);e:=Degree(pt);assert d mod e eq 0;cl:=(d div e)*ph(Divisor(pt)-e*A);Append(~rows,[*d,Eltseq(cl),cl in H*]);if #rows mod 20 eq 0 then print "D31B_C54_PROFILE_PROGRESS",#rows,Cputime(tm);end if;end for;fprintf wh,"]\n";Flush(wh);Write(root cat "profile100_expanded_classes.m",Sprint(rows):Overwrite:=true);print "D31B_C54_EXPANDED_PROFILE_COMPLETE",#rows,#[v:v in rows|v[3]],Cputime(tm),Cputime(tt);quit;
